"use server";
import { revalidatePath } from "next/cache";
import { auth } from "../../../auth";
import db from "@/lib/prisma";
import { exigirAcessoConfigPipeline } from "@/lib/bpm/ownership";
import { notificarPipelineBpm } from "@/lib/bpm/realtime-server";
import { FINANCIAL_FIELDS, FINANCIAL_PIPELINE_NAME, FINANCIAL_PIPELINE_SCHEMA_VERSION, FINANCIAL_STAGES, financialStageKeyFromLabel } from "@/lib/bpm/pipeline-financeiro";
export async function ConfigurarPipelineFinanceiro(pipelineId: string) {
  try {
    const session = await auth(); if (!session?.user?.id) return { success: false, error: "Não autorizado" }; const userId = Number(session.user.id); await exigirAcessoConfigPipeline(userId, "configurarEtapas");
    const result = await db.$transaction(async (tx) => {
      await exigirAcessoConfigPipeline(userId, "configurarEtapas", tx);
      const pipeline = await tx.bpmPipeline.findUnique({ where: { id: pipelineId }, include: { etapas: { where: { ativo: true }, orderBy: { ordem: "asc" } }, campos: true } }); if (!pipeline || pipeline.nome !== FINANCIAL_PIPELINE_NAME) throw new Error("Pipeline Financeiro não encontrado");
      const etapasAtivas = [...pipeline.etapas];
      const etapasUsadas = new Set<string>();
      const stageByKey = new Map<string, (typeof etapasAtivas)[number]>();
      for (const [index, definition] of FINANCIAL_STAGES.entries()) {
        const candidatasSemanticas = etapasAtivas.filter((etapa) => !etapasUsadas.has(etapa.id) && financialStageKeyFromLabel(etapa.nome) === definition.key);
        const existing = candidatasSemanticas.find((etapa) => etapa.nome === definition.label)
          ?? candidatasSemanticas[0]
          ?? etapasAtivas.find((etapa) => !etapasUsadas.has(etapa.id) && financialStageKeyFromLabel(etapa.nome) === null);
        const etapa = existing
          ? await tx.bpmEtapa.update({ where: { id: existing.id }, data: { nome: definition.label, ordem: index } })
          : await tx.bpmEtapa.create({ data: { pipelineId, nome: definition.label, ordem: index } });
        etapasUsadas.add(etapa.id);
        stageByKey.set(definition.key, etapa);
      }
      const etapas = FINANCIAL_STAGES.map((definition) => {
        const etapa = stageByKey.get(definition.key);
        if (!etapa) throw new Error("Etapa financeira não configurada");
        return etapa;
      });
      const etapasExcedentes = etapasAtivas.filter((etapa) => !etapasUsadas.has(etapa.id));
      if (etapasExcedentes.length > 0) {
        for (const etapaExcedente of etapasExcedentes) {
          const chaveDestino = financialStageKeyFromLabel(etapaExcedente.nome) ?? "concluidos";
          const etapaDestino = stageByKey.get(chaveDestino);
          if (!etapaDestino) throw new Error("Etapa financeira de destino não configurada");
          await tx.bpmCard.updateMany({ where: { etapaId: etapaExcedente.id }, data: { etapaId: etapaDestino.id } });
        }
        await tx.bpmEtapa.updateMany({ where: { id: { in: etapasExcedentes.map((etapa) => etapa.id) } }, data: { ativo: false } });
      }
      const fields = [];
      for (const [ordem, definition] of FINANCIAL_FIELDS.entries()) {
        const etapa = stageByKey.get(definition.stage);
        if (!etapa) throw new Error("Etapa financeira não configurada");
        const existing = pipeline.campos.find((campo) => campo.nome === definition.label);
        const data = {
          nome: definition.label,
          tipo: definition.type,
          opcoesJson: definition.options ? JSON.stringify(definition.options) : null,
          ordem,
        };
        const campo = existing
          ? await tx.bpmCampo.update({ where: { id: existing.id }, data })
          : await tx.bpmCampo.create({ data: { pipelineId, ...data } });
        await tx.bpmCampoEtapaConfig.upsert({
          where: { campoId_etapaId: { campoId: campo.id, etapaId: etapa.id } },
          create: {
            campoId: campo.id,
            etapaId: etapa.id,
            visivel: true,
            editavel: true,
            somenteLeitura: false,
            obrigatorio: definition.category === "OBRIGATORIO",
            ordem,
          },
          update: { obrigatorio: definition.category === "OBRIGATORIO", ordem },
        });
        fields.push(campo);
      }
      for (const origem of etapas) {
        for (const destino of etapas) {
          if (origem.id === destino.id) continue;
          const permitida = etapas.indexOf(destino) === etapas.indexOf(origem) + 1;
          await tx.bpmTransicaoEtapa.upsert({
            where: { etapaOrigemId_etapaDestinoId: { etapaOrigemId: origem.id, etapaDestinoId: destino.id } },
            create: { pipelineId, etapaOrigemId: origem.id, etapaDestinoId: destino.id, permitida, origem: "AMBOS" },
            update: { permitida, origem: "AMBOS" },
          });
        }
      }
      await tx.bpmPipelineConfigAuditoria.create({ data: { pipelineId, adminId: userId, campoAlterado: "pipeline_financeiro_schema_aplicado", valorNovoJson: JSON.stringify({ schemaVersion: FINANCIAL_PIPELINE_SCHEMA_VERSION, etapas: FINANCIAL_STAGES.length, campos: FINANCIAL_FIELDS.length }) } }); return { etapas, campos: fields };
    });
    revalidatePath(`/PainelAlpha/AlphaCRM/admin/pipelines/${pipelineId}`); revalidatePath(`/PainelAlpha/AlphaCRM/pipeline/${pipelineId}`); try { await notificarPipelineBpm({ pipelineId, tipo: "PIPELINE_ALTERADO" }); } catch (error) { console.error("[ConfigurarPipelineFinanceiro:notificacao_pos_commit]", error); } return { success: true, data: result };
  } catch (error) { console.error("[ConfigurarPipelineFinanceiro]", error); return { success: false, error: error instanceof Error ? error.message : "Não foi possível configurar o pipeline Financeiro" } }
}
